// Filled in at build time by vite.config.ts (D65): the version and the commit this build came from.
declare const __APP_VERSION__: string;
/** Short commit hash; a trailing + means it was built with uncommitted changes; "dev" without git. */
declare const __APP_COMMIT__: string;
/** The commit on GitHub, or '' when it isn't there as built. */
declare const __APP_COMMIT_URL__: string;
